   982	func parseAgeCutoff(value string, now time.Time) (time.Time, error) {
   983		value = strings.TrimSpace(value)
   984		if strings.HasSuffix(value, "d") {
   985			days, err := strconv.Atoi(strings.TrimSuffix(value, "d"))
   986			if err != nil || days < 0 {
   987				return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
   988			}
   989			return now.Add(-time.Duration(days) * 24 * time.Hour), nil
   990		}
   991		duration, err := time.ParseDuration(value)
   992		if err != nil {
   993			return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
   994		}
   995		return now.Add(-duration), nil
   996	}
