  1092			return err
  1093		}
  1094		if err := addBundlePath(tw, storage.BrainDir, activeSnapshot); err != nil {
  1095			_ = f.Close()
  1096			return err
  1097		}
  1098		if err := tw.Close(); err != nil {
  1099			_ = f.Close()
  1100			return err
  1101		}
  1102		if err := f.Close(); err != nil {
  1103			return err
  1104		}
  1105		checksum := hex.EncodeToString(hasher.Sum(nil))
  1106		if err := appendSemanticAudit(storage.BrainDir, "bundle_export", output, checksum); err != nil {
  1107			return err
