  1154	func rejectBundleOutputInsideBrain(output, brainDir string) error {
  1155		outputAbs, err := filepath.Abs(output)
  1156		if err != nil {
  1157			return err
  1158		}
  1159		brainAbs, err := filepath.Abs(brainDir)
  1160		if err != nil {
  1161			return err
  1162		}
  1163		if pathInside(brainAbs, outputAbs) {
  1164			return fmt.Errorf("bundle output must be outside the active brain directory: %s", output)
  1165		}
  1166		outputResolved, err := resolvedOutputPath(output)
  1167		if err != nil {
  1168			return err
  1169		}
  1170		brainResolved, err := filepath.EvalSymlinks(brainDir)
  1171		if err != nil {
  1172			brainResolved = brainAbs
  1173		}
  1174		if pathInside(brainResolved, outputResolved) {
  1175			return fmt.Errorf("bundle output must be outside the active brain directory: %s", output)
  1176		}
  1177		return nil
  1178	}
