  1180	func pathInside(root, path string) bool {
  1181		rel, err := filepath.Rel(root, path)
  1182		if err != nil {
  1183			return false
  1184		}
  1185		return rel == "." || (!strings.HasPrefix(rel, ".."+string(filepath.Separator)) && rel != "..")
  1186	}
  1187	
  1188	func resolvedOutputPath(output string) (string, error) {
  1189		if resolved, err := filepath.EvalSymlinks(output); err == nil {
  1190			return filepath.Abs(resolved)
  1191		}
  1192		parent := filepath.Dir(output)
  1193		resolvedParent, err := filepath.EvalSymlinks(parent)
  1194		if err != nil {
  1195			resolvedParent, err = filepath.Abs(parent)
  1196			if err != nil {
  1197				return "", err
  1198			}
  1199		}
  1200		return filepath.Abs(filepath.Join(resolvedParent, filepath.Base(output)))
  1201	}
