  1203	func runSemanticBundleImport(ctx context.Context, cmd *cobra.Command, opts Options, archive, expectedChecksum string) error {
  1204		if err := rejectRemoteBundlePath(archive); err != nil {
  1205			return err
  1206		}
  1207		expectedChecksum = strings.ToLower(strings.TrimSpace(expectedChecksum))
  1208		if len(expectedChecksum) != sha256.Size*2 {
  1209			return errors.New("expected bundle checksum must be a hex SHA-256 digest")
  1210		}
  1211		f, err := os.Open(archive)
  1212		if err != nil {
  1213			return err
  1214		}
  1215		defer f.Close()
  1216		sum, err := readerSHA256(f)
  1217		if err != nil {
  1218			return err
  1219		}
  1220		if sum != expectedChecksum {
  1221			return fmt.Errorf("bundle checksum mismatch: got %s, want %s", sum, expectedChecksum)
  1222		}
  1223		repoDir, err := exportRepoDir(opts.Env)
  1224		if err != nil {
  1225			return err
  1226		}
  1227		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
  1228		if err != nil {
  1229			return err
  1230		}
  1231		unlock, err := acquireSemanticIndexLock(storage.BrainDir)
  1232		if err != nil {
  1233			return err
  1234		}
  1235		defer unlock()
  1236		if _, err := f.Seek(0, io.SeekStart); err != nil {
  1237			return err
  1238		}
  1239		if err := os.MkdirAll(filepath.Dir(storage.BrainDir), 0o700); err != nil {
  1240			return err
  1241		}
  1242		tmpDir, err := os.MkdirTemp(filepath.Dir(storage.BrainDir), ".bundle-import-*")
  1243		if err != nil {
  1244			return err
  1245		}
  1246		defer os.RemoveAll(tmpDir)
  1247		tr := tar.NewReader(f)
  1248		imported := 0
  1249		var totalBytes int64
  1250		for {
  1251			header, err := tr.Next()
  1252			if errors.Is(err, io.EOF) {
  1253				break
  1254			}
  1255			if err != nil {
  1256				return err
  1257			}
  1258			if err := validateBundleEntry(header); err != nil {
  1259				return err
  1260			}
  1261			if header.Size > semanticBundleMaxEntry {
  1262				return fmt.Errorf("bundle entry too large: %s", header.Name)
  1263			}
  1264			imported++
  1265			if imported > semanticBundleMaxFiles {
  1266				return fmt.Errorf("bundle has too many entries: %d", imported)
  1267			}
  1268			totalBytes += header.Size
  1269			if totalBytes > semanticBundleMaxTotal {
  1270				return fmt.Errorf("bundle total size exceeds limit: %d", totalBytes)
  1271			}
  1272			target := filepath.Join(tmpDir, filepath.FromSlash(header.Name))
  1273			if err := os.MkdirAll(filepath.Dir(target), 0o700); err != nil {
  1274				return err
  1275			}
  1276			out, err := os.OpenFile(target, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
  1277			if err != nil {
  1278				return err
  1279			}
  1280			_, copyErr := io.CopyN(out, tr, header.Size)
  1281			closeErr := out.Close()
  1282			if copyErr != nil {
  1283				return copyErr
  1284			}
  1285			if closeErr != nil {
  1286				return closeErr
  1287			}
  1288		}
  1289		importManifest, err := validateImportedBundle(tmpDir, storage.Key)
  1290		if err != nil {
  1291			return err
  1292		}
  1293		if err := filepath.WalkDir(tmpDir, func(path string, d os.DirEntry, walkErr error) error {
  1294			if walkErr != nil {
  1295				return walkErr
  1296			}
  1297			if d.IsDir() {
  1298				return nil
  1299			}
  1300			rel, err := filepath.Rel(tmpDir, path)
  1301			if err != nil {
  1302				return err
  1303			}
  1304			if rel == exportManifestFileName {
  1305				return nil
  1306			}
  1307			if filepath.ToSlash(rel) != importManifest.Sources.Semantic.SnapshotPath {
  1308				return nil
  1309			}
  1310			content, err := os.ReadFile(path)
  1311			if err != nil {
  1312				return err
  1313			}
