  1315		}); err != nil {
  1316			return err
  1317		}
  1318		if err := writeBrainSemanticSource(storage.BrainDir, storage.Key, importManifest.Sources.Semantic); err != nil {
  1319			return err
  1320		}
  1321		if err := appendSemanticAudit(storage.BrainDir, "bundle_import", archive, sum); err != nil {
  1322			return err
  1323		}
  1324		fmt.Fprintf(cmd.OutOrStdout(), "imported bundle entries: %d\nsha256: %s\n", imported, sum)
  1325		return nil
  1326	}
